sys_script.script:
(function executeRule(current, previous) {

    /* =====================================================
       NEXORA - AUTO CREATE INTERVIEW  (ONE FILE, NO DUPLICATES)

       Table : Application
       When  : AFTER   |  Insert + Update   |  Condition: (empty)
       Paste ONLY this code in the business rule. Nothing else.
       ===================================================== */

    var IV = 'x_snc_college_pl_0_interview';

    function norm(v) {
        return (v || '').toString().toLowerCase().replace(/[\s_-]/g, '').trim();
    }

    function isScheduled(v) {
        v = norm(v);
        return v === 'interviewscheduled' || v === 'scheduled';
    }

    function isClosedRec(gr) {
        var t = norm(gr.getValue('status')) + '|' + norm(gr.getDisplayValue('status'));
        return t.indexOf('complete') >= 0 || t.indexOf('cancel') >= 0 || !!gr.getValue('result');
    }

    /* Keep the OLDEST open interview of this application, delete the rest */
    function removeDuplicates(appId) {

        var kept = '';
        var g = new GlideRecord(IV);
        g.addQuery('application', appId);
        g.orderBy('sys_created_on');
        g.query();

        while (g.next()) {

            if (isClosedRec(g)) { continue; }

            if (!kept) { kept = g.getUniqueValue(); continue; }

            g.deleteRecord();
        }
    }


    /* 1. Only when application is Interview Scheduled */

    if (!isScheduled(current.getValue('status')) && !isScheduled(current.getDisplayValue('status'))) {
        return;
    }

    var appId = current.getUniqueValue();


    /* 2. Did status just change to Scheduled? */

    var justChanged = true;

    if (current.operation() === 'update' && previous) {
        justChanged = !(isScheduled(previous.getValue('status')) || isScheduled(previous.getDisplayValue('status')));
    }


    /* 3. Existing interviews for this application */

    var total = 0, open = 0;

    var ex = new GlideRecord(IV);
    ex.addQuery('application', appId);
    ex.query();

    while (ex.next()) {
        total++;
        if (!isClosedRec(ex)) { open++; }
    }

    if (open > 0) {
        removeDuplicates(appId);        /* clean any old duplicates too */
        return;
    }

    if (total > 0 && !justChanged) {
        return;
    }


    /* 4. Create ONE interview */

    var iv = new GlideRecord(IV);
    iv.initialize();
    iv.setValue('application', appId);

    if (iv.isValidField('drive') && current.isValidField('drive') && current.getValue('drive')) {
        iv.setValue('drive', current.getValue('drive'));
    }

    if (iv.isValidField('status')) {

        var ch = new GlideRecord('sys_choice');
        ch.addQuery('name', IV);
        ch.addQuery('element', 'status');
        ch.addQuery('inactive', false);
        ch.query();

        while (ch.next()) {
            if (norm(ch.getValue('value')).indexOf('notset') >= 0 || norm(ch.getValue('label')).indexOf('notset') >= 0) {
                iv.setValue('status', ch.getValue('value'));
                break;
            }
        }
    }

    var id = iv.insert();

    if (id) {
        removeDuplicates(appId);        /* if two ran together, only the oldest survives */
        gs.info('[NEXORA] Interview created ' + id + ' for ' + current.getDisplayValue());
    } else {
        gs.error('[NEXORA] Interview NOT created for ' + current.getDisplayValue() + ' : ' + iv.getLastErrorMessage());
    }

})(current, previous);
